"""Génère docs/sources/2am/unit2/extraction.json — 2AM, unité 2 « الكسور والعمليات عليها » (manuel الجيل الثاني,
منشورات الشهاب ; pp. 22–37 du livre = PDF 19–34, décalage 3 — docs/sources/2am/textbook-map.json).

Transcription VISUELLE (pages rendues à 110 dpi ; les passages de la leçon qisma-iqlidiya-hasr relus à 200–300 dpi). Le
scan de 2AM est la seule copie et il est médiocre (décision D5/D9 : on prend l'idée, on ne s'attarde pas sur l'illisible).
Les éléments des leçons qui ne sont pas encore générées (kasr-hasil-qisma, jam-tarh-kusur, jida-kasrayn, muqarana-kasrayn,
la synthèse) sont transcrits plus brièvement et marqués `verified: False` : leur leçon les relira. Les réponses sont
CALCULÉES ici (Fraction et entiers exacts), jamais tapées.

L'unité est générée LEÇON PAR LEÇON : les destinations vers une leçon encore coming_soon sont EN ATTENTE
(scripts/check-textbook-coverage.mjs).

FRONTIÈRES (copie de plan/README.md « Boundaries ») : qisma-iqlidiya-hasr = division euclidienne, a/b entre deux naturels consécutifs, noms
« قيمة مقرّبة إلى الوحدة » ; kasr-hasil-qisma = « نسبة a إلى b », « كتابة كسرية », ×10ⁿ pour diviser par un décimal, valeurs par défaut / par
excès à 0,1 · 0,01 · 0,001 (jamais l'arrondi au plus proche, 3AM) ; jam-tarh-kusur = a/c ± b/c et dénominateur multiple ; jida-kasrayn = produit
et fraction D'UNE quantité ; muqarana-kasrayn = même dénominateur / même numérateur / multiple / 1 intermédiaire ; la synthèse n'introduit rien.

Usage : python3 docs/sources/2am/unit2/build-extraction.py
"""
import json
from decimal import Decimal as D
from fractions import Fraction as F
from itertools import combinations
from pathlib import Path


def dec(s):
    return D(str(s).replace(',', '.'))


def fr(x):
    """Un décimal exact écrit à l'algérienne (virgule)."""
    x = D(x).normalize()
    return format(x, 'f').replace('.', ',')


def frac(x):
    x = F(x)
    return str(x.numerator) if x.denominator == 1 else f'{x.numerator}/{x.denominator}'


def q(s):
    """Un « nombre » du manuel en Fraction exacte : '7/4', '4,5/3', '1,75', '12'."""
    s = str(s)
    if '/' in s:
        n, d = s.split('/')
        return F(dec(n)) / F(dec(d))
    return F(dec(s))


def euclid(a, b):
    qq, r = divmod(a, b)
    return {'q': qq, 'r': r, 'eq': f'{a} = {b} × {qq} + {r}', 'bracket': [qq, qq + 1] if r else [qq, qq]}


def mixed(a, b):
    """a/b = q + r/b (la « décomposition anglo-saxonne » de l'exercice 33)."""
    qq, r = divmod(a, b)
    return f'{a}/{b} = {qq} + {frac(F(r, b))}'


